from __future__ import annotations

"""Mobile V1 home: Stock Flow only, served from the official App Ready snapshot.

The landing page is an operational over-ordering dashboard. Legacy urgent-home
nodes are removed at runtime. Stock Flow reads the production snapshot endpoint;
it must never depend on the historical RC route.
"""

_STYLE = r'''<style id="yipmanV1StockFlowOnlyHomeStyle">
#quick #urgentSummary,#quick #updated,#quick .v1-home-switch{display:none!important}.v1-flow-controls{display:grid;gap:7px;margin:2px 0 8px}.v1-flow-control-row{display:grid;grid-template-columns:auto minmax(150px,1fr);gap:8px;align-items:center}.v1-flow-window{display:grid;grid-template-columns:repeat(3,1fr);gap:5px}.v1-flow-window button{height:38px;border:1px solid #344653;border-radius:11px;background:#101820;color:#95a5b1;font-size:12px;font-weight:1000}.v1-flow-window button.active{background:#214d70;color:#fff;border-color:#528ab2}.v1-flow-sort{height:38px;width:100%;border:1px solid #344653;border-radius:11px;background:#101820;color:#edf4f8;padding:0 9px;font-size:12px;font-weight:1000}.v1-flow-caption{border:1px solid #273845;border-radius:10px;background:#0f171e;padding:7px 9px;color:#8ca0ae;font-size:11px;font-weight:900}.v1-flow-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin:0 0 9px}.v1-flow-summary div{border:1px solid #2d3d49;border-radius:11px;background:#101820;padding:7px 5px;text-align:center}.v1-flow-summary b{display:block;font-size:18px}.v1-flow-summary span{display:block;margin-top:2px;color:#8295a3;font-size:9px;font-weight:1000}.v1-flow-card{border-left-width:6px!important}.v1-flow-card.over{border-left-color:#e0a84d!important}.v1-flow-card.under{border-left-color:#67aee4!important}.v1-flow-card.balanced{border-left-color:#67bb7b!important}.v1-flow-action-row{display:flex;align-items:center;justify-content:space-between;gap:9px;margin-top:8px}.v1-flow-action{font-size:20px;font-weight:1000}.v1-flow-diff{border:1px solid #435463;border-radius:999px;padding:5px 8px;background:#101920;font-size:12px;font-weight:1000}.v1-flow-compare,.v1-flow-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:7px}.v1-flow-mainmetric,.v1-flow-metric{border:1px solid #354958;border-radius:12px;background:#0e1921;padding:8px;text-align:center}.v1-flow-mainmetric b,.v1-flow-metric b{display:block;color:#7f94a4;font-size:9px}.v1-flow-mainmetric strong{display:block;margin-top:4px;font-size:19px}.v1-flow-metric strong{display:block;margin-top:3px;font-size:14px}.v1-flow-reason{margin-top:7px;color:#a9b7c1;font-size:12px;line-height:1.35;font-weight:800}@media(max-width:390px){.v1-flow-control-row{grid-template-columns:1fr}}
</style>'''

_SCRIPT = r'''<script id="yipmanV1StockFlowOnlyHomeScript">
(()=>{'use strict';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const num=v=>{const x=Number(v);return Number.isFinite(x)?x:null};const fmt=(v,d=1)=>{const x=num(v);return x===null?'—':x.toLocaleString(undefined,{maximumFractionDigits:d})};let days=7,rows=[],payload=null,loading=false,sortKey='diffpct',painting=false;const cache=new Map(),list=()=>document.getElementById('urgentList'),q=()=>String(document.getElementById('quickSearch')?.value||'').trim();function stripLegacy(){document.querySelector('#quick #urgentSummary')?.remove();document.querySelector('#quick #updated')?.remove();document.querySelectorAll('#quick .v1-home-switch').forEach(x=>x.remove())}function ensure(){stripLegacy();const top=document.querySelector('#quick .top');if(!top||document.getElementById('v1FlowControls'))return;const w=document.createElement('div');w.innerHTML=`<div id="v1FlowControls" class="v1-flow-controls"><div class="v1-flow-control-row"><div class="v1-flow-window"><button data-flow-days="7" class="active">7D</button><button data-flow-days="14">14D</button><button data-flow-days="28">28D</button></div><select class="v1-flow-sort" id="v1FlowSort"><option value="diffpct">SORT: DIFFERENCE % ↓</option><option value="overpct">OVER-ORDER % ↓</option><option value="selling">SELLING MVT ↓</option><option value="receipts">RECEIPTS ↓</option><option value="oh">EFFECTIVE OH ↓</option></select></div><div class="v1-flow-caption" id="v1FlowCaption">Stock Flow · receipts vs selling movement</div></div><div id="v1FlowSummary" class="v1-flow-summary"><div><b>—</b><span>OVER ORDER</span></div><div><b>—</b><span>UNDER RECEIPT</span></div><div><b>—</b><span>BALANCED</span></div></div>`;while(w.firstChild)top.appendChild(w.firstChild);top.querySelectorAll('[data-flow-days]').forEach(b=>b.onclick=()=>{days=+b.dataset.flowDays;top.querySelectorAll('[data-flow-days]').forEach(x=>x.classList.toggle('active',x===b));load(true)});document.getElementById('v1FlowSort').onchange=e=>{sortKey=e.target.value;render()}}function pct(r){const x=num(r.receipt_vs_selling_difference_pct);if(x!==null)return x;const s=num(r.family_group_movement_qty),rc=num(r.family_receipt_qty);return s&&rc!==null?(rc-s)/s*100:null}function sorted(){const a=[...rows],p=r=>pct(r);if(sortKey==='overpct')a.sort((x,y)=>(p(y)??-999999)-(p(x)??-999999));else if(sortKey==='selling')a.sort((x,y)=>(num(y.family_group_movement_qty)||0)-(num(x.family_group_movement_qty)||0));else if(sortKey==='receipts')a.sort((x,y)=>(num(y.family_receipt_qty)||0)-(num(x.family_receipt_qty)||0));else if(sortKey==='oh')a.sort((x,y)=>(num(y.effective_oh)||0)-(num(x.effective_oh)||0));else a.sort((x,y)=>Math.abs(p(y)??0)-Math.abs(p(x)??0));return a}function render(){if(q())return;ensure();const box=list();if(!box)return;painting=true;const c=payload?.signal_counts||{},b=document.querySelectorAll('#v1FlowSummary b');if(b[0])b[0].textContent=c.OVER_ORDER_WATCH||0;if(b[1])b[1].textContent=c.UNDER_ORDER_WATCH||0;if(b[2])b[2].textContent=c.BALANCED||0;const shown=sorted();box.innerHTML=shown.length?shown.map(r=>{const s=num(r.family_group_movement_qty)||0,rc=num(r.family_receipt_qty)||0,p=pct(r),over=r.flow_signal==='OVER_ORDER_WATCH',under=r.flow_signal==='UNDER_ORDER_WATCH',cls=over?'over':under?'under':'balanced',u=r.family_group_movement_uom||'',label=over?'OVER-ORDER WATCH':under?'UNDER-RECEIPT WATCH':'BALANCED FLOW';return `<article class="urgent-card v1-flow-card ${cls}"><div class="urgent-top"><div><div class="urgent-name">${esc(r.family_name||'Family')}</div><div class="urgent-meta">Family ${esc(r.family_article||r.family_id||'—')}</div></div><span class="pill ${over?'warn':under?'blue':'good'}">${days}D FLOW</span></div><div class="v1-flow-action-row"><div class="v1-flow-action">${label}</div><div class="v1-flow-diff">${p===null?'—':(p>=0?'+':'')+fmt(p,0)+'%'}</div></div><div class="v1-flow-compare"><div class="v1-flow-mainmetric"><b>SELLING MVT</b><strong>${fmt(s)} ${esc(u)}</strong></div><div class="v1-flow-mainmetric"><b>RECEIPT QTY</b><strong>${fmt(rc)} ${esc(u)}</strong></div></div><div class="v1-flow-grid"><div class="v1-flow-metric"><b>DIFFERENCE</b><strong>${rc-s>=0?'+':''}${fmt(rc-s)} ${esc(u)}</strong></div><div class="v1-flow-metric"><b>EFFECTIVE OH</b><strong>${fmt(r.effective_oh)} ${esc(r.effective_oh_uom||u)}</strong></div></div><div class="v1-flow-reason">${over?'Receipts are above supported selling movement. Review the next regular/promotion order before adding stock.':under?'Selling movement is above receipts. Check upcoming delivery coverage.':'Receipt and selling flow are within the comparison band.'}</div></article>`}).join(''):'<div class="empty">No Stock Flow rows for this selected window.</div>';setTimeout(()=>painting=false,0)}async function load(force=false){ensure();if(q())return;const k=String(days);if(!force&&cache.has(k)){payload=cache.get(k);rows=payload.rows||[];render();return}if(loading)return;loading=true;const box=list();if(box)box.innerHTML='<div class="loading">Loading Stock Flow…</div>';try{const res=await fetch('/api/yipman/app-ready/section/stock_flow',{credentials:'same-origin',cache:'no-store'});if(!res.ok)throw Error('HTTP '+res.status);const snap=await res.json();const section=snap?.section||snap?.payload||snap||{};payload=section;rows=section.rows||[];cache.set(k,payload);render()}catch(e){if(box)box.innerHTML='<div class="empty">Stock Flow unavailable · '+esc(e.message)+'</div>'}finally{loading=false}}function guard(){const box=list();if(!box)return;new MutationObserver(()=>{stripLegacy();if(painting||q()||!rows.length)return;const hasFlow=!!box.querySelector('.v1-flow-card');if(!hasFlow)render()}).observe(box,{childList:true,subtree:false})}const boot=()=>{ensure();guard();load();const i=document.getElementById('quickSearch');if(i)i.addEventListener('input',()=>{if(!q())load()})};document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot):setTimeout(boot,0)})();
</script>'''

def polish_stock_flow_home_html(html:str)->str:
    if 'yipmanV1StockFlowOnlyHomeStyle' in html:return html
    return html.replace('</head>',_STYLE+'</head>',1).replace('</body>',_SCRIPT+'</body>',1)
